9	// critical section. That is what makes concurrent identical requests yield
10	// exactly one 201 and what keeps balances from ever being seen mid-move.
11	func (s *Store) Idempotent(userID, method, path, key string, body map[string]any,
12		fn func(st *State) (any, *AppError)) (int, []byte, *AppError) {
13		if e := CheckIdemKey(key); e != nil {
14			return 0, nil, e
15		}
16		canon := trCanonBody(body)
17		rk := trIdemKey(userID, method, path, key)
18	
19		s.mu.Lock()
20		defer s.mu.Unlock()
21	
22		if rec, ok := s.st.Sys.Idem[rk]; ok && rec != nil {
23			if rec.Body != canon {
24				return 0, nil, NewErr(409, "idempotency_key_reuse", "Idempotency-Key was already used with a different request body")
25			}
26			return 200, append([]byte(nil), rec.Resp...), nil
27		}
28	
29		v, e := fn(s.st)
30		if e != nil {
31			return 0, nil, e
32		}
33		resp, err := MarshalJSON(v)
34		if err != nil {
35			return 0, nil, NewErr(500, "internal_error", "could not encode response")
36		}
37		if s.st.Sys.Idem == nil {
38			s.st.Sys.Idem = map[string]*IdemRecord{}
39		}
40		s.st.Sys.Idem[rk] = &IdemRecord{Body: canon, Resp: append([]byte(nil), resp...)}
41		return 201, resp, nil
