55	// one microsecond, so a read sees every earlier write. It does not advance anything.
56	func (st *State) ReadNow(now time.Time) time.Time {
57		t := now.UTC().Truncate(time.Microsecond)
58		if !st.lastStamp.IsZero() {
59			if floor := st.lastStamp.Add(time.Microsecond); t.Before(floor) {
